import csv
import io
text = 'item,units\nBox,2\nTape\nBag,\nPen,1,extra\n'
reader = csv.DictReader(io.StringIO(text))
headers = reader.fieldnames or []
valid = len(headers) == 2 and set(headers) == {"item", "units"}
if not valid:
    print("BAD HEADER")
else:
    for row in reader:
        item = (row.get("item") or "").strip()
        units = (row.get("units") or "").strip()
        if None in row or not item or not units:
            print("SKIP")
        else:
            print("READY", item)
